SELECT COUNT(*) FROM votes as v, comments as c, posts as p, postHistory as ph, users as u WHERE u.Id = c.UserId AND p.Id = c.PostId AND u.Id = v.UserId AND p.Id = ph.PostId AND c.Score=0 AND c.CreationDate>=CAST('2010-07-20 06:26:28' AS TIMESTAMP) AND c.CreationDate<=CAST('2014-09-11 18:45:09' AS TIMESTAMP) AND p.PostTypeId=1 AND p.FavoriteCount>=0 AND p.FavoriteCount<=2 AND ph.PostHistoryTypeId=5
